insert:
// wow-forever patch: 2% Agility a rank (client 70205's trait node 110859; the spell 19168 the fork reads still says 3%). The factor
// corrects the line below to 1 + 0.02 x rank and is 1 once the fork reads the trait's value.
hunter.MultiplyStat(stats.Agility, (1+0.02*float64(hunter.Talents.LightningReflexes))/spellData.LightningReflexes.MultiplierAt(hunter.Talents.LightningReflexes))

if noRacials() { // wow-forever patch: WOW_FOREVER_NO_RACIALS=1 (patches/forever/sim/core/no_racials.go)
	return
}

with:
func (e *Effect) Coeff() float64 {
	return e.SPCoef * DownrankMultiplier(e.SpellID) // wow-forever patch: Forever's downranking penalty (patches/forever/sim/core/spelldata/downrank.go)
}
